package iq.yasserapps.studio;
import android.app.*;import android.os.*;import android.content.*;import android.net.Uri;import android.graphics.Color;import android.widget.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.util.concurrent.*;
public class MainActivity extends Activity {
 final ExecutorService worker=Executors.newSingleThreadExecutor();File current,exportApk;ApkEngine.Result result;TextView status,report;Button edit,save,choose,dexSearch,dexEdit,verify,again;boolean busy;String exportText;
 static final int GREEN=0xff39ff7a,BG=0xff101310;
 public void onCreate(Bundle b){super.onCreate(b);getWindow().setStatusBarColor(BG);getWindow().setNavigationBarColor(BG);ScrollView sc=new ScrollView(this);LinearLayout root=new LinearLayout(this);root.setOrientation(1);root.setPadding(dp(20),dp(24),dp(20),dp(20));root.setBackgroundColor(BG);sc.addView(root);setContentView(sc);root.addView(text("YASSERAPPS STUDIO",26,GREEN));root.addView(text("APK LAB • V0.3 • تحليل محلي",14,0xffa3b5aa));choose=button("اختيار ملف APK",()->startActivityForResult(new Intent(Intent.ACTION_OPEN_DOCUMENT).setType("*/*").addCategory(Intent.CATEGORY_OPENABLE),1));root.addView(choose);status=text("اختر تطبيقاً تملك حق تحليله وتعديله.",16,Color.WHITE);root.addView(status);edit=button("تحرير ملف نصي مصرح به",()->pickAsset());root.addView(edit);dexSearch=button("البحث داخل دوال DEX",()->dexDialog(false));root.addView(dexSearch);dexEdit=button("تعديل نص برمجي مصرح به",()->dexDialog(true));root.addView(dexEdit);verify=button("فحص توقيع APK",()->signature());root.addView(verify);again=button("تصدير آخر APK",()->exportLast());root.addView(again);save=button("تصدير تقرير التحليل",()->{exportText=report.getText().toString();startActivityForResult(new Intent(Intent.ACTION_CREATE_DOCUMENT).setType("text/plain").putExtra(Intent.EXTRA_TITLE,"YASSERAPPS-analysis.txt"),2);});root.addView(save);report=text("لا يوجد ملف محمّل.",14,0xffd0ddd3);report.setTextIsSelectable(true);root.addView(report);root.addView(text("نسخة اختبار: تحرير نصوص assets وتعليمات const-string المحددة فقط، لا تغيير منطق الحماية أو التراخيص. التوقيع بمفتاح محلي جديد.",13,0xffa3b5aa));state(false,"جاهز");}
 int dp(int v){return Math.round(getResources().getDisplayMetrics().density*v);}
 TextView text(String s,int n,int c){TextView t=new TextView(this);t.setText(s);t.setTextSize(n);t.setTextColor(c);return t;}
 Button button(String s,Runnable r){Button b=new Button(this);b.setText(s);b.setAllCaps(false);b.setTextColor(GREEN);b.setOnClickListener(v->{if(!busy)r.run();});return b;}
 void state(boolean b,String s){busy=b;status.setText(s);choose.setEnabled(!b);edit.setEnabled(!b&&result!=null&&!result.assets.isEmpty());save.setEnabled(!b&&result!=null);dexSearch.setEnabled(!b&&result!=null&&result.dex>0);dexEdit.setEnabled(!b&&result!=null&&result.dex>0);verify.setEnabled(!b&&current!=null);again.setEnabled(!b&&exportApk!=null);}
 void fail(Exception e){runOnUiThread(()->state(false,"خطأ: "+e.getMessage()));}
 String identity(File f){try{android.content.pm.PackageInfo p=getPackageManager().getPackageArchiveInfo(f.getAbsolutePath(),android.content.pm.PackageManager.GET_PERMISSIONS);if(p!=null)return "الحزمة: "+p.packageName+"\nالإصدار: "+p.versionName+"\nالأذونات: "+(p.requestedPermissions==null?"لا توجد":String.join(", ",p.requestedPermissions));}catch(Exception ignored){}return "تعذر قراءة معلومات الحزمة";}
 protected void onActivityResult(int req,int code,Intent data){super.onActivityResult(req,code,data);if(code!=RESULT_OK||data==null||data.getData()==null)return;Uri uri=data.getData();
 if(req==1){state(true,"جاري التحليل");worker.submit(()->{File f=null;try{f=File.createTempFile("source-",".apk",getCacheDir());try(InputStream in=getContentResolver().openInputStream(uri);OutputStream out=new FileOutputStream(f)){if(in==null)throw new IOException("Cannot open");ApkEngine.copy(in,out,1024L*1024*1024);}ApkEngine.Result r=ApkEngine.scan(f);File next=f;String id=identity(f);runOnUiThread(()->{if(current!=null)current.delete();if(exportApk!=null){exportApk.delete();exportApk=null;}current=next;result=r;report.setText(id+"\n"+r.report());state(false,"تم التحليل");});}catch(Exception e){if(f!=null)f.delete();fail(e);}});}
 if(req==2||req==3){state(true,"تصدير");File f=exportApk;String txt=exportText;worker.submit(()->{try(OutputStream out=getContentResolver().openOutputStream(uri,"wt")){if(out==null)throw new IOException("Cannot export");if(req==2)out.write(txt.getBytes(StandardCharsets.UTF_8));else try(InputStream in=new FileInputStream(f)){ApkEngine.copy(in,out,1024L*1024*1024);}runOnUiThread(()->state(false,"تم حفظ الملف"));}catch(Exception e){fail(e);}});}
 }
 void pickAsset(){String[] ns=result.assets.toArray(new String[0]);new AlertDialog.Builder(this).setTitle("اختر ملفاً نصياً").setItems(ns,(d,i)->editor(ns[i])).show();}
 void editor(String name){File src=current;state(true,"قراءة الملف");worker.submit(()->{try{String original=ApkEngine.asset(src,name);runOnUiThread(()->{state(false,name);LinearLayout l=new LinearLayout(this);l.setOrientation(1);l.setPadding(dp(16),0,dp(16),0);TextView sample=text(original.substring(0,Math.min(1500,original.length())),12,Color.WHITE);sample.setTextIsSelectable(true);l.addView(sample);EditText a=new EditText(this),b=new EditText(this);a.setHint("النص القديم (تطابق واحد)");b.setHint("النص الجديد");l.addView(a);l.addView(b);CheckBox c=new CheckBox(this);c.setText("أملك حق تعديل التطبيق");l.addView(c);ScrollView s=new ScrollView(this);s.addView(l);AlertDialog dlg=new AlertDialog.Builder(this).setTitle(name).setView(s).setNegativeButton("إلغاء",null).setPositiveButton("معاينة",null).create();dlg.setOnShowListener(v->dlg.getButton(-1).setOnClickListener(w->{String old=a.getText().toString(),replacement=b.getText().toString();int p=original.indexOf(old);if(!c.isChecked()||old.isEmpty()||old.equals(replacement)||p<0||original.indexOf(old,p+1)>=0){a.setError("تأكيد الصلاحية وتطابق واحد مطلوب");return;}dlg.dismiss();new AlertDialog.Builder(this).setTitle("مراجعة التعديل").setMessage("قبل: "+old+"\nبعد: "+replacement+"\nالتوقيع المحلي مختلف عن الأصلي. احتفظ بالنسخة الأصلية وبياناتها.").setNegativeButton("إلغاء",null).setPositiveButton("إعادة البناء",(x,y)->build(src,name,old,replacement)).show();}));dlg.show();});}catch(Exception e){fail(e);}});}
 void build(File src,String n,String a,String b){state(true,"إعادة البناء والتوقيع");worker.submit(()->{File unsigned=null,signed=null;try{unsigned=File.createTempFile("unsigned-",".apk",getCacheDir());signed=File.createTempFile("signed-",".apk",getCacheDir());ApkEngine.rebuild(src,unsigned,n,a,b);LocalSigner.sign(unsigned,signed);if(!ApkEngine.asset(signed,n).contains(b))throw new IOException("Edited asset missing");File f=signed;runOnUiThread(()->{if(exportApk!=null)exportApk.delete();exportApk=f;state(false,"تم التوقيع والتحقق؛ التثبيت غير مختبر");startActivityForResult(new Intent(Intent.ACTION_CREATE_DOCUMENT).setType("application/vnd.android.package-archive").putExtra(Intent.EXTRA_TITLE,"YASSERAPPS-local-signed.apk"),3);});}catch(Exception e){if(signed!=null)signed.delete();fail(e);}finally{if(unsigned!=null)unsigned.delete();}});}
 void exportLast(){startActivityForResult(new Intent(Intent.ACTION_CREATE_DOCUMENT).setType("application/vnd.android.package-archive").putExtra(Intent.EXTRA_TITLE,"YASSERAPPS-local-signed.apk"),3);}
 void signature(){File f=current;state(true,"فحص التوقيع");worker.submit(()->{try{com.android.apksig.ApkVerifier.Result r=new com.android.apksig.ApkVerifier.Builder(f).build().verify();StringBuilder t=new StringBuilder("\n\nSignature verified: "+r.isVerified()+"\nV1: "+r.isVerifiedUsingV1Scheme()+" V2: "+r.isVerifiedUsingV2Scheme()+" V3: "+r.isVerifiedUsingV3Scheme()+"\n"+r.getErrors());for(java.security.cert.X509Certificate c:r.getSignerCertificates())t.append("\n").append(c.getSubjectX500Principal().getName());runOnUiThread(()->{report.append(t);state(false,"اكتمل فحص التوقيع");});}catch(Exception e){fail(e);}});}
 void dexDialog(boolean change){LinearLayout l=new LinearLayout(this);l.setOrientation(1);l.setPadding(dp(16),0,dp(16),0);EditText old=new EditText(this);old.setHint("النص البرمجي الكامل (مطابقة حرفية)");l.addView(old);EditText replacement=new EditText(this);replacement.setHint("النص الجديد");CheckBox confirm=new CheckBox(this);confirm.setText("أملك حق تعديل هذا النص؛ لا أغيّر منطق الترخيص أو الحماية");if(change){l.addView(replacement);l.addView(confirm);}AlertDialog dlg=new AlertDialog.Builder(this).setTitle(change?"معاينة نص DEX":"البحث عن نص DEX").setView(l).setPositiveButton("بحث",null).setNegativeButton("إلغاء",null).create();dlg.setOnShowListener(v->dlg.getButton(-1).setOnClickListener(w->{String a=old.getText().toString(),b=replacement.getText().toString();if(a.isEmpty()||a.length()>2048||change&&(!confirm.isChecked()||a.equals(b)||b.length()>2048)){old.setError("راجع النص والصلاحية");return;}dlg.dismiss();locate(current,a,b,change);}));dlg.show();}
 void locate(File f,String a,String b,boolean change){state(true,"تحليل تعليمات DEX");worker.submit(()->{try{java.util.List<DexTools.Hit> hits=DexTools.find(f,a);runOnUiThread(()->{state(false,"عدد المطابقات: "+hits.size());if(hits.isEmpty()){new AlertDialog.Builder(this).setMessage("لا توجد تعليمات const-string مطابقة حرفياً. قد يكون النص ضمن الموارد أو يُجلب من الشبكة.").setPositiveButton("حسناً",null).show();return;}String[] names=new String[hits.size()];for(int i=0;i<names.length;i++)names[i]=hits.get(i).label();new AlertDialog.Builder(this).setTitle(change?"اختر التعليمة المراد تعديلها":"مواقع النص داخل الكود").setItems(names,(d,i)->{if(change)new AlertDialog.Builder(this).setTitle("تأكيد تعديل تعليمة واحدة").setMessage(names[i]+"\nقبل: "+a+"\nبعد: "+b+"\nسيعاد بناء DEX وتوقيع نسخة منفصلة. قد لا تعمل بعض التطبيقات.").setNegativeButton("إلغاء",null).setPositiveButton("تنفيذ",(x,y)->buildDex(f,hits.get(i),a,b)).show();}).setNegativeButton("إغلاق",null).show();});}catch(Exception e){fail(e);}});}
 void buildDex(File src,DexTools.Hit h,String a,String b){state(true,"إعادة بناء DEX والتوقيع");worker.submit(()->{File unsigned=null,signed=null;try{unsigned=File.createTempFile("dex-unsigned-",".apk",getCacheDir());signed=File.createTempFile("dex-signed-",".apk",getCacheDir());DexTools.replace(src,unsigned,h,a,b);LocalSigner.sign(unsigned,signed);File f=signed;runOnUiThread(()->{if(exportApk!=null)exportApk.delete();exportApk=f;state(false,"تم البناء والتحقق من التوقيع؛ تشغيل التطبيق غير مختبر");exportLast();});}catch(Exception e){if(signed!=null)signed.delete();fail(e);}finally{if(unsigned!=null)unsigned.delete();}});}
 public static String selfTestLiteral(){return "YASSERAPPS_STUDIO_FIXTURE_030";}
 protected void onDestroy(){worker.shutdownNow();super.onDestroy();}
}